interface DigitalPomodoraProps {
  focusSessions: FocusSession[];
  onAllocateSession: (session: Omit<FocusSession, 'id' | 'timestamp'> & { id?: string; timestamp?: string; chapterName?: string; relevance?: 'General' | 'Revision' | 'Final Revision'; revKey?: RevisionCycleKey }) => Promise<void>;
  onDeleteSession: (id: string) => Promise<void>;
  
  sleepSessions: { id: string; startTime: string; endTime: string; duration: number; feeling?: string }[];
  isSleeping?: boolean;
  sleepStartTime?: string | null;
  onStartSleep: () => void;
  onStopSleep: (feeling?: string) => void;
  onDeleteSleepSession: (id: string) => void;
  onAddSleepSession?: (session: { id?: string; startTime: string; endTime: string; duration: number; feeling?: string }) => void;
  
  activeFocusTask: { id?: string; subjectCode: string; title: string; cleanTitle?: string; chapterName?: string; relevance?: 'General' | 'Revision' | 'Final Revision'; completed?: boolean; dueDate?: string; revKey?: RevisionCycleKey; targetDurationMinutes?: number; isUntimedOpen?: boolean } | null;
  onClearActiveFocusTask: () => void;
  onAllocateActiveFocusTask: (elapsedMinutes: number) => Promise<void>;
  onCompleteLinkedTask?: (task: any) => Promise<void> | void;

  // Daily target compliance states passed from App.tsx
  dailyGoalMinutes: number;
  onUpdateDailyGoal: (minutes: number) => void;
  
  onStartFocusForTask?: (subjectCode: string, title: string, durationMinutes?: number, chapterName?: string, relevance?: 'General' | 'Revision' | 'Final Revision', dueDate?: string, revKey?: RevisionCycleKey, taskId?: string, isUntimedOpen?: boolean) => void;
  onGoToPlanner?: () => void;
  onGoToRevisionPlanner?: () => void;

  // Power Nap & Rest Channel props
  onRequestRestMode?: () => void;
  isPowerNapping?: boolean;
  powerNapTimeLeftSeconds?: number;
  powerNapTargetMins?: number;
  onStopPowerNap?: (feeling?: string) => void;
  onShareProgress?: () => void;
}

