export interface RoutineTimeWindow {
  name: string;
  allowedText: string;
  isAllowed: (hours: number, minutes: number) => boolean;
}

export const ROUTINE_TIME_WINDOWS: Record<string, RoutineTimeWindow> = {
  breakfast: {
    name: 'Breakfast',
    allowedText: '4:00 AM – 12:00 PM',
    isAllowed: (h, m) => {
      const totalMins = h * 60 + m;
      return totalMins >= 4 * 60 && totalMins < 12 * 60;
    }
  },
  lunch: {
    name: 'Lunch',
    allowedText: '12:00 PM – 6:00 PM',
    isAllowed: (h, m) => {
      const totalMins = h * 60 + m;
      return totalMins >= 12 * 60 && totalMins < 18 * 60;
    }
  },
  dinner: {
    name: 'Dinner',
    allowedText: '6:00 PM – 4:00 AM',
    isAllowed: (h, m) => {
      const totalMins = h * 60 + m;
      return totalMins >= 18 * 60 || totalMins < 4 * 60;
    }
  }
};

export const getRoutineMealWindow = (routineLabelOrId?: string): RoutineTimeWindow | null => {
  if (!routineLabelOrId) return null;
  const norm = routineLabelOrId.trim().toLowerCase();
  if (norm === 'breakfast') return ROUTINE_TIME_WINDOWS.breakfast;
  if (norm === 'lunch') return ROUTINE_TIME_WINDOWS.lunch;
  if (norm === 'dinner') return ROUTINE_TIME_WINDOWS.dinner;
  return null;
};

export const checkRoutineTimeEligibility = (
  routineLabelOrId?: string,
  timeToCheck?: { hours: number; minutes: number } | Date | string | null
): { isEligible: boolean; caption?: string; allowedRange?: string } => {
  const windowConfig = getRoutineMealWindow(routineLabelOrId);
  if (!windowConfig) {
    return { isEligible: true };
  }

  let h: number;
  let m: number;

  if (!timeToCheck) {
    const now = new Date();
    h = now.getHours();
    m = now.getMinutes();
  } else if (timeToCheck instanceof Date) {
    h = timeToCheck.getHours();
    m = timeToCheck.getMinutes();
  } else if (typeof timeToCheck === 'string') {
    const parts = timeToCheck.split(':').map(Number);
    if (parts.length >= 2 && !isNaN(parts[0]) && !isNaN(parts[1])) {
      h = parts[0];
      m = parts[1];
    } else {
      const now = new Date();
      h = now.getHours();
      m = now.getMinutes();
    }
  } else {
    h = timeToCheck.hours;
    m = timeToCheck.minutes;
  }

  const isEligible = windowConfig.isAllowed(h, m);
  if (!isEligible) {
    return {
      isEligible: false,
      allowedRange: windowConfig.allowedText,
      caption: `${windowConfig.name} is only eligible between ${windowConfig.allowedText}.`
    };
  }

  return { isEligible: true, allowedRange: windowConfig.allowedText };
};



