              const READING_DURATION_SECS = 15 * 60; // 15 minutes (900 seconds)
              const EXAM_DURATION_SECS = (activeMockTest.initialMockMins || 180) * 60; // 3 hours (10,800 seconds)
              const TOTAL_SCHEDULED_SECS = activeMockTest.totalDurationSeconds || (READING_DURATION_SECS + EXAM_DURATION_SECS);
              const startMs = activeMockTest.startTime || (blockStartTime ? blockStartTime.getTime() : wallTime.getTime());
              const elapsedSecs = Math.max(0, Math.floor((wallTime.getTime() - startMs) / 1000));

              const isReadingPhase = elapsedSecs < READING_DURATION_SECS;
              const readingRemainingSecs = isReadingPhase ? Math.max(0, READING_DURATION_SECS - elapsedSecs) : 0;
              const examElapsedSecs = isReadingPhase ? 0 : Math.max(0, elapsedSecs - READING_DURATION_SECS);
              const examRemainingSecs = isReadingPhase ? EXAM_DURATION_SECS : Math.max(0, EXAM_DURATION_SECS - examElapsedSecs);

              const isExamTimeCompleted = elapsedSecs >= TOTAL_SCHEDULED_SECS;
              const overtimeSecs = isExamTimeCompleted ? Math.max(0, elapsedSecs - TOTAL_SCHEDULED_SECS) : 0;
              const autoCloseRemainingSecs = Math.max(0, 60 - overtimeSecs);
              const autoCloseMins = Math.floor(autoCloseRemainingSecs / 60);
              const autoCloseSecs = autoCloseRemainingSecs % 60;
              const formattedAutoCloseMMSS = `${String(autoCloseMins).padStart(2, '0')}:${String(autoCloseSecs).padStart(2, '0')}`;
              const autoClosePercentRemaining = Math.max(0, Math.min(100, (autoCloseRemainingSecs / 60) * 100));

              const activeCountdownSecs = isReadingPhase ? readingRemainingSecs : examRemainingSecs;
              const activePhaseTotalSecs = isReadingPhase ? READING_DURATION_SECS : EXAM_DURATION_SECS;
              const phasePercentRemaining = Math.max(0, Math.min(100, (activeCountdownSecs / activePhaseTotalSecs) * 100));

              const hrs = Math.floor(activeCountdownSecs / 3600);
              const mins = Math.floor((activeCountdownSecs % 3600) / 60);
              const secs = activeCountdownSecs % 60;
              const formattedHHMMSS = `${String(hrs).padStart(2, '0')}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;

