                        isReadingPhase
                          ? 'text-amber-300 bg-amber-500/15 border-amber-500/40 shadow-amber-500/10'
                          : 'text-cyan-300 bg-cyan-500/15 border-cyan-500/40 shadow-cyan-500/10'
