                    <div className="flex items-center justify-between text-xs font-mono pt-2 border-t border-slate-900">
                      <span className="text-slate-400">Selected Mock Exam Duration:</span>
                      <span className="text-amber-300 font-black">
                        {(() => {
                          const dur = computeDurationFrom24h(mockLogStartTime, mockLogEndTime);
                          return `${dur} mins (${Math.floor(dur / 60)}h ${dur % 60}m)`;
                        })()}
                      </span>
                    </div>
